 {
  "from": "member",
  "time": "2026-09-14 08:12",
  "text": "also there's a zelle for $425 on sunday, that's from my roommate jess, her half of the rent. that one's fine lol"
 },
 {
  "from": "agent (Priya, Cedar Ridge FCU)",
  "time": "2026-09-14 08:15",
  "text": "Thank you. So you are disputing three transactions: ATM $400.00 (09/12 10:02), ATM $400.00 (09/12 10:05) and TechZone $289.97 (09/12 10:21). Does anyone else know your PIN?"
