 },
 {
  "from": "agent (Priya, Cedar Ridge FCU)",
  "time": "2026-09-14 08:27",
  "text": "We'll complete our review within 10 business days and let you know about any provisional credit. The locker rental would be something to take up with the gym directly."
 }
