[
 {
  "zaman": "30.09.2026 08:47",
  "kimden": "Derya Kocabaş (Kredi Riski İzleme)",
  "mesaj": "Günaydın. Q3 kapanışı (30.09.2026) için RG-0417 Yamaç risk grubunu bugün bitirmemiz lazım. Müşteri 70112'nin K-1 taksiti (18.400.000 TL) 24.06.2026 vadeliydi, hâlâ ödenmedi. Diğer kalemlerde gecikme görünmüyor."
 },
 {
  "zaman": "30.09.2026 08:55",
  "kimden": "Derya Kocabaş (Kredi Riski İzleme)",
  "mesaj": "Yönetmelik 5/5 ve 5/6'yı buraya bırakıyorum. (5): 'Borçlusunun aynı banka tarafından verilmiş birden çok kredisinin mevcut bulunması ve bu kredilerden herhangi birinin yapılan sınıflandırma gereği donuk alacak olarak kabul edilmesi durumunda, söz konusu borçlunun bankadan kullanmış olduğu tüm kredileri donuk alacak olarak aynı grupta sınıflandırılır.' (6): 'Borçlunun kredilerinin donuk alacak olarak sınıflandırılması halinde, borçlunun dâhil olduğu risk grubu içerisinde yer alan diğer borçluların kredi değerliliği de sınıflandırma tarihinde ayrıca değerlendirilir ve 4 üncü maddede belirtilen koşulların taşınması halinde bunların kredileri de donuk alacak olarak sınıflandırılır.'"
 },
 {
  "zaman": "30.09.2026 09:03",
  "kimden": "Onur Saygılı (Kurumsal Analiz)",
  "mesaj": "Gruptaki açık krediler: K-1 (müşteri 70112, proje finansmanı, bakiye 142.000.000 TL), K-2 (müşteri 70112, rotatif, limit 25.000.000 TL, faizler her ay düzenli ödeniyor), K-5 (müşteri 70345, makine yatırım kredisi, bakiye 38.600.000 TL, gecikme 0), K-7 (müşteri 81920, konut kredisi, bakiye 4.150.000 TL, gecikme 0)."
 },
 {
  "zaman": "30.09.2026 09:10",
  "kimden": "Melis Ardıç (Yasal Raporlama)",
  "mesaj": "Bir de Yamaçlar Lojistik var, onu da gruba ekleyelim mi? İsim çok benziyor."
 },
 {
  "zaman": "30.09.2026 09:14",
  "kimden": "Onur Saygılı (Kurumsal Analiz)",
  "mesaj": "Yok, Yamaçlar Lojistik'in ortakları Bursalı Tekin ailesi; Yamaç grubuyla sermaye ya da yönetim bağı yok, RG-0417'de değil. Grup kaydı şöyle: 70112 Yamaç İnşaat Taahhüt A.Ş., 70345 Yamaç Hazır Beton San. ve Tic. A.Ş., 81920 Kerem Yamaç (iki şirketin de %60 ortağı)."
 },
 {
  "zaman": "30.09.2026 09:26",
  "kimden": "Derya Kocabaş (Kredi Riski İzleme)",
  "mesaj": "Hazır Beton'u konuşalım. Cirosunun %35'i Yamaç İnşaat şantiyelerine gidiyor, İnşaat'tan 14,2 milyon TL alacağı 60 günü geçmiş. Bence kredi riskinde önemli artış var, K-5'i Aşama 2'ye alalım."
 },
 {
  "zaman": "30.09.2026 09:31",
  "kimden": "Onur Saygılı (Kurumsal Analiz)",
  "mesaj": "Katılmıyorum. Hazır Beton'un 41 milyon TL nakdi var, son üç yıl kârlı, bize bir gün bile gecikmedi. Ağustos'ta Kocaeli'de iki büyük kamu projesi için beton tedarik sözleşmesi imzaladı. İnşaat'taki alacak hiç tahsil edilmese bile özkaynağının %9'u eder. Bence Aşama 1'de kalsın, bir çeyrek yakından izleyelim."
 },
 {
  "zaman": "30.09.2026 09:38",
  "kimden": "Derya Kocabaş (Kredi Riski İzleme)",
  "mesaj": "Ama patron aynı; İnşaat batarsa Hazır Beton'un nakdi gruba çekilebilir. İç derecesi de Şubat'tan beri güncellenmedi, en son 6/12 idi. TO modeli bu ay da aynı TO'yu basıyor çünkü girdiler eski."
 },
 {
  "zaman": "30.09.2026 09:44",
  "kimden": "Melis Ardıç (Yasal Raporlama)",
  "mesaj": "Kerem Bey'in konut kredisi için ne yapıyoruz? Grup şirketi temerrüde düştü diye otomatik donuk mu oluyor?"
 },
 {
  "zaman": "30.09.2026 09:49",
  "kimden": "Onur Saygılı (Kurumsal Analiz)",
  "mesaj": "5/5 aynı borçlunun kredileri için. Kerem Bey ayrı bir borçlu, 5/6'ya göre ayrıca değerlendiriyoruz. Konut kredisi düzenli ödeniyor, kira gelirleri şirketlerden bağımsız; şu an 4. maddedeki donuk alacak koşullarından hiçbirini taşımıyor."
 },
